os.environ["FLASHINFER_DISABLE_VERSION_CHECK"] = "1"
import json, time
from vllm import LLM, SamplingParams
from vllm.sampling_params import StructuredOutputsParams

schema = {
    "type": "object",
    "properties": {
        "entities": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "text": {"type": "string"},
                    "type": {"type": "string", "enum": ["person", "location", "organization"]}
                },
                "required": ["text", "type"]
            }
        }
    },
    "required": ["entities"]
}

prompt = "Extract named entities from: 'Barack Obama visited the White House in Washington DC with representatives from the United Nations.'\nReturn JSON:"

llm = LLM(
    model="/root/autodl-tmp/.hf_cache/qwen3-32b-fp8/",
    trust_remote_code=True, dtype="bfloat16",
    max_model_len=4096, gpu_memory_utilization=0.95,
    enforce_eager=True, disable_log_stats=True,
)
print(f"Model loaded", flush=True)

structured_params = StructuredOutputsParams(json=schema)
sampling_params = SamplingParams(max_tokens=512, temperature=0.0, structured_outputs=structured_params)

t0 = time.time()
outputs = llm.generate([prompt], sampling_params)
elapsed = time.time() - t0
text = outputs[0].outputs[0].text
print(f"Elapsed: {elapsed:.1f}s", flush=True)
print(f"OUTPUT: {text}", flush=True)
try:
    parsed = json.loads(text)
    print(f"VALID JSON: {json.dumps(parsed, indent=2)}", flush=True)
    print("STRUCTURED_OUTPUT_TEST_PASSED")
except json.JSONDecodeError as e:
    print(f"JSON PARSE ERROR: {e}", flush=True)
    print("STRUCTURED_OUTPUT_TEST_FAILED")
